# dmgbuild settings for the Ferrocord disk image (packaging/macos/package.sh).
#
# Run as:
#   dmgbuild -s dmg-settings.py -D app=<Ferrocord.app> -D background=<background.png> \
#            -D icon=<Ferrocord.icns> "Ferrocord" <out.dmg>
#
# The layout must match the artwork in packaging/macos/dmg/background*.png
# (generated by packaging/installer-art/generate.py): a 660x400 window with the
# app on the left of the arrow and the Applications link on the right.
import os.path

app = defines["app"]  # noqa: F821 (injected by dmgbuild)
app_name = os.path.basename(app)

# ULFO: LZFSE-compressed, read-only. Smaller and faster to open than UDZO; macOS 10.11+.
format = "ULFO"
filesystem = "HFS+"
size = None

files = [app]
symlinks = {"Applications": "/Applications"}
hide_extensions = [app_name]
icon = defines["icon"]  # noqa: F821  volume icon shown in Finder and on the desktop

# A PNG; dmgbuild finds background@2x.png beside it and combines both into one HiDPI TIFF.
background = defines["background"]  # noqa: F821
show_status_bar = False
show_tab_view = False
show_toolbar = False
show_pathbar = False
show_sidebar = False
window_rect = ((200, 120), (660, 400))
default_view = "icon-view"
show_icon_preview = False
arrange_by = None
icon_size = 112
text_size = 13
label_pos = "bottom"
icon_locations = {
    app_name: (170, 205),
    "Applications": (490, 205),
}
